#include <iostream>
#include <memory>
#include <functional>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <atomic>
#include <cstdlib>
#include <cstring>
#include <cstdint>
#include <limits>

namespace ml_inference {

struct ModelConfig {
    int batch_size;
    int max_sequence_length;
    float temperature;
    char model_path[256];
};

class TensorBuffer {
public:
    float* data;
    size_t size;

    TensorBuffer(size_t sz) : size(sz) {
        data = new float[sz];
        memset(data, 0, sz * sizeof(float));
    }

    ~TensorBuffer() {
        delete[] data;
        data = nullptr;
    }

    TensorBuffer(const TensorBuffer&) = delete;
    TensorBuffer& operator=(const TensorBuffer&) = delete;
};

using InferenceCallback = std::function<void(const float*, size_t)>;

// Reasonable upper bounds to prevent integer overflow / excessive allocation
static constexpr int kMaxBatchSize = 4096;
static constexpr int kMaxSeqLen = 65536;
static constexpr int kMaxPipelineDepth = 1024;

class AsyncInferenceEngine {
private:
    struct PendingRequest {
        TensorBuffer* input_buffer;
        InferenceCallback callback;
        int priority;
    };

    std::queue<PendingRequest> request_queue_;
    std::mutex queue_mutex_;
    std::condition_variable queue_cv_;
    std::atomic<bool> running_{true};
    std::thread worker_thread_;
    ModelConfig config_;
    int pipeline_depth_;

    void worker_loop() {
        while (running_.load()) {
            PendingRequest req;
            {
                std::unique_lock<std::mutex> lock(queue_mutex_);
                queue_cv_.wait(lock, [this] {
                    return !request_queue_.empty() || !running_.load();
                });
                if (!running_.load() && request_queue_.empty()) return;
                req = std::move(request_queue_.front());
                request_queue_.pop();
            }
            execute_inference(req);
        }
    }

    void execute_inference(PendingRequest& req) {
        // Simulate model inference with configurable pipeline depth.
        // Compute output size with overflow protection since batch_size and
        // max_sequence_length originate from external (env) configuration.
        size_t batch = static_cast<size_t>(config_.batch_size);
        size_t seq = static_cast<size_t>(config_.max_sequence_length);
        size_t output_size = 0;
        if (batch != 0 && seq > std::numeric_limits<size_t>::max() / batch) {
            // Overflow would occur; fall back to a safe bounded value.
            output_size = static_cast<size_t>(kMaxBatchSize) * static_cast<size_t>(kMaxSeqLen);
        } else {
            output_size = batch * seq;
        }
        if (output_size == 0) {
            // Nothing to compute; still invoke callback with empty result.
            req.callback(nullptr, 0);
            delete req.input_buffer;
            return;
        }

        TensorBuffer output(output_size);

        for (size_t i = 0; i < output_size && i < req.input_buffer->size; i++) {
            output.data[i] = req.input_buffer->data[i] * config_.temperature;
        }

        // Pipeline stages based on environment config
        for (int stage = 0; stage < pipeline_depth_; stage++) {
            for (size_t i = 0; i < output_size; i++) {
                output.data[i] = output.data[i] * 0.99f + 0.01f;
            }
        }

        // Invoke callback with results - req.input_buffer may be accessed in callback
        req.callback(output.data, output_size);

        // Cleanup input after callback
        delete req.input_buffer;
    }

    // Validate and clamp a parsed integer config value into [min, max].
    static int clamp_int(int value, int min_v, int max_v, int fallback) {
        if (value < min_v || value > max_v) {
            return fallback;
        }
        return value;
    }

public:
    AsyncInferenceEngine() {
        const char* batch_env = getenv("ML_BATCH_SIZE");
        const char* seq_env = getenv("ML_MAX_SEQ_LEN");
        const char* temp_env = getenv("ML_TEMPERATURE");
        const char* depth_env = getenv("ML_PIPELINE_DEPTH");

        // Validate and clamp externally-supplied configuration to prevent
        // integer overflow / excessive allocation (CWE-190 / CWE-20).
        int parsed_batch = batch_env ? atoi(batch_env) : 32;
        int parsed_seq = seq_env ? atoi(seq_env) : 512;
        int parsed_depth = depth_env ? atoi(depth_env) : 3;

        config_.batch_size = clamp_int(parsed_batch, 1, kMaxBatchSize, 32);
        config_.max_sequence_length = clamp_int(parsed_seq, 1, kMaxSeqLen, 512);
        pipeline_depth_ = clamp_int(parsed_depth, 0, kMaxPipelineDepth, 3);

        float parsed_temp = temp_env ? static_cast<float>(atof(temp_env)) : 1.0f;
        if (!(parsed_temp > 0.0f) || parsed_temp > 1000.0f) {
            parsed_temp = 1.0f;
        }
        config_.temperature = parsed_temp;

        strncpy(config_.model_path, "/models/default", sizeof(config_.model_path) - 1);
        config_.model_path[sizeof(config_.model_path) - 1] = '\0';

        worker_thread_ = std::thread(&AsyncInferenceEngine::worker_loop, this);
    }

    ~AsyncInferenceEngine() {
        running_.store(false);
        queue_cv_.notify_all();
        if (worker_thread_.joinable()) worker_thread_.join();
    }

    void submit_request(float* input_data, size_t input_size, InferenceCallback cb, int priority = 0) {
        TensorBuffer* buf = new TensorBuffer(input_size);
        memcpy(buf->data, input_data, input_size * sizeof(float));

        {
            std::lock_guard<std::mutex> lock(queue_mutex_);
            request_queue_.push({buf, std::move(cb), priority});
        }
        queue_cv_.notify_one();
    }
};

class InferenceSession {
private:
    AsyncInferenceEngine& engine_;
    std::vector<float> last_result_;
    std::mutex result_mutex_;
    std::condition_variable result_cv_;
    bool result_ready_ = false;
    std::vector<float> owned_input_copy_;

public:
    InferenceSession(AsyncInferenceEngine& engine) : engine_(engine) {}

    std::vector<float> run_inference(float* input, size_t size) {
        owned_input_copy_.assign(input, input + size);
        result_ready_ = false;

        // Capture 'this' and use owned copy for post-processing in callback
        engine_.submit_request(input, size, [this](const float* output, size_t out_size) {
            std::lock_guard<std::mutex> lock(result_mutex_);
            last_result_.assign(output, output + out_size);

            // Post-process: blend with original input for residual connection
            // Uses owned_input_copy_ which is a safe member copy
            for (size_t i = 0; i < out_size && i < owned_input_copy_.size(); i++) {
                last_result_[i] += owned_input_copy_[i] * 0.1f;
            }

            result_ready_ = true;
            result_cv_.notify_one();
        });

        std::unique_lock<std::mutex> lock(result_mutex_);
        result_cv_.wait(lock, [this] { return result_ready_; });
        return last_result_;
    }
};

} // namespace ml_inference

int main() {
    ml_inference::AsyncInferenceEngine engine;

    auto run_batch = [&engine]() {
        ml_inference::InferenceSession session(engine);
        {
            std::vector<float> input(1024, 1.0f);
            auto result = session.run_inference(input.data(), input.size());
            if (!result.empty()) {
                std::cout << "Result[0]: " << result[0] << std::endl;
            }
        }
    };

    std::vector<std::thread> threads;
    for (int i = 0; i < 4; i++) {
        threads.emplace_back(run_batch);
    }
    for (auto& t : threads) t.join();

    return 0;
}
